enabled(m: number[]): number[] {
    return this.t.map((_, t) => t).filter((t) => !this.reason(m, t));
commit(t: number): void {
    this.history.push(this.current);
    this.current = this.fire(this.current, t);
        case "SIMULATE": {
            const steps = integer(args[0], 1, 1000);
            let x = integer(args[1], 1, 2147483646);
            if (steps < 0) fail("invalid steps " + args[0]);
            if (x < 0) fail("invalid seed " + args[1]);
            if (!["PRIORITY", "RANDOM"].includes(args[2])) fail("invalid mode " + args[2]);
            const counts = this.t.map(() => 0);
            let done = 0;
            for (; done < steps; ++done) {
                const e = this.enabled(this.current);
                if (!e.length) {
                    out(`dead (steps=${done})`);
                    break;
                }
                let t = e[0];
                if (args[2] === "RANDOM") {
                    x = (x * 48271) % 2147483647;
                    t = e[x % e.length];
                } else for (const u of e) if (this.prio[u] > this.prio[t]) t = u;
                this.commit(t);
                ++counts[t];
                out(`step ${done + 1}: ${this.t[t]} -> ${marking(this.current)}`);
            }
            if (done === steps) out(`completed (steps=${steps})`);
            out("counts: " + this.t.map((n, t) => n + "=" + counts[t]).join(" "));
